                        "worker_id",
                        "quest_id",
                        "plan_id",
                        "plan_revision",
                        "plan_digest",
                        "team_digest",
                        "generation",
                        "lease_token",
                        "lease_until",
                        "deadline",
                        "state",
                        "provider_id",
                        "model_id",
                        "execution_mode",
                    )
                },
                "capsule": dict(capsule_row),
                "archive_head": dict(head) if head else None,
                "message_hashes": [
